"""Criteria for `init-output-needs-a-drain`.

The criterion checks “which line, which rule, and whether it was waived,” not the full message text—the message may
change, while line number and rule name are the contract.
"""

from pathlib import Path

from _checks import init_output

PREAMBLE = "import pypto_pro.language as pl\n\n\n"

TILE = "pl.TileType(shape=[8, 8], dtype=pl.DT_FP32, target_memory=pl.MemorySpace.Vec)"

INIT = "    pl.init_output(out, offset=0, size=64, value=-1.0)\n"


def _write(
    tmp_path: Path, body: str, *, decorator: str = "@pl.jit()", docstring: str = ""
) -> Path:
    doc = f'    """{docstring}\n    """\n' if docstring else ""
    text = PREAMBLE + f"{decorator}\ndef _kernel(x, out):\n" + doc + body
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    return path


BODY = 6
"""Line number of the first function-body line in files generated by `_write` (one import line + two blank lines +
decorator + def)."""


def _hits(path: Path) -> list[tuple[int, str, bool]]:
    return [
        (finding.lineno, finding.rule, finding.waived)
        for finding in init_output.check(path)
    ]


# ---------------------------------------------------------------------------
# Reported cases
# ---------------------------------------------------------------------------


def test_init_output_next_to_a_bare_tile_is_reported(tmp_path):
    """The core case for this rule. It failed 6 of 12 board runs, with wrong values taken from input `x` (see the table
    in the module docstring).
    """
    path = _write(
        tmp_path,
        INIT + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    assert _hits(path) == [(BODY, init_output.RULE, False)]


def test_it_reports_on_the_init_output_line_not_the_tile_line(tmp_path):
    """Report on the `init_output` line: the missing barrier beside that line is the fix, not the Tile declaration.

    Tile line numbers may also appear in the message (there can be several), but the diagnostic anchor is unique.
    """
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        f"    dst = pl.make_tile({TILE}, addr=0x1000)\n"
        + INIT.replace("    pl.", "    pl.")
        + "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    hits = init_output.check(path)
    assert [(hit.lineno, hit.rule) for hit in hits] == [(BODY + 2, init_output.RULE)]
    assert f"第 {BODY} 行、第 {BODY + 1} 行" in hits[0].message


def test_a_tile_made_by_a_helper_counts(tmp_path):
    """Few examples write the long `make_tile(TileType(...))` form directly; they wrap it in `_tile()`.
    **The motivating case for this rule, `init_and_insert`, does exactly that**—recognizing only literal `pl.make_tile`
    calls would miss every one of its Tiles. The message must name the helper used, or readers will search for a
    `make_tile` call that is not there.
    """
    text = (
        PREAMBLE
        + f"def _tile(shape, addr):\n    return pl.make_tile({TILE}, addr=addr)\n"
        "\n\n@pl.jit()\ndef _kernel(x, out):\n"
        "    pl.init_output(out, offset=0, size=64, value=-1.0)\n"
        "    src = _tile([8, 8], 0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    hits = init_output.check(path)
    assert [(hit.lineno, hit.rule, hit.waived) for hit in hits] == [
        (10, init_output.RULE, False)
    ]
    assert "第 11 行（经 `_tile`）" in hits[0].message


def test_a_helper_that_makes_a_group_is_not_a_bare_tile(tmp_path):
    """Do not treat every helper as a source of bare Tiles: a helper wrapping `make_tile_group` is still the safe form.
    Classification depends on which API the helper actually calls.
    """
    text = (
        PREAMBLE + "def _group(shape, addr):\n"
        f"    return pl.make_tile_group(type={TILE}, addrs=addr, mutex_ids=[0])\n"
        "\n\n@pl.jit()\ndef _kernel(x, out):\n"
        "    pl.init_output(out, offset=0, size=64, value=-1.0)\n"
        "    g = _group([8, 8], 0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(g.current(), x, [0, 0])\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == []


def test_auto_mutex_does_not_count_as_protection(tmp_path):
    """**Measured:** `auto_mutex=True` plus a bare Tile still fails 6 of 12 runs, and its generated C++ is textually
    identical to the `@pl.jit()` variant. `make_tile_group`, not `auto_mutex`, emits `get_buf`; this pins that
    attribution, which I previously got wrong.
    """
    path = _write(
        tmp_path,
        INIT + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        decorator="@pl.jit(auto_mutex=True)",
    )
    assert _hits(path) == [(BODY, init_output.RULE, False)]


def test_two_init_outputs_give_two_findings(tmp_path):
    """Report once per `init_output`: each one needs its own drain, so fixing one does not fix the others."""
    path = _write(
        tmp_path,
        INIT
        + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        + INIT
        + "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    assert _hits(path) == [
        (BODY, init_output.RULE, False),
        (BODY + 2, init_output.RULE, False),
    ]


def test_kernels_built_by_a_factory_are_checked(tmp_path):
    """Inspect nested definitions too—the address probe in `init_and_insert` is created by a factory, so a
    module-scope-only scan misses it entirely.
    """
    text = (
        PREAMBLE + "def _make(addr):\n"
        "    @pl.jit()\n"
        "    def kernel(x, out):\n"
        "        pl.init_output(out, offset=0, size=64, value=-1.0)\n"
        f"        src = pl.make_tile({TILE}, addr=addr)\n"
        "        with pl.section_vector():\n"
        "            pl.load(src, x, [0, 0])\n"
        "    return kernel\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == [(7, init_output.RULE, False)]


# ---------------------------------------------------------------------------
# Non-reported cases: these determine whether the tool is a useful gate or noise.
# ---------------------------------------------------------------------------


def test_bar_all_silences_the_rule(tmp_path):
    """Measured 0 failures in 12 runs. This is one of the fixes accepted by the rule."""
    path = _write(
        tmp_path,
        INIT
        + "    pl.system.bar_all()\n"
        + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    assert _hits(path) == []


def test_a_tile_group_silences_the_rule(tmp_path):
    """Another fix: `make_tile_group` emits `get_buf(PIPE_MTE2, 0, 0)`, which uses the same buffer ID as `init_output`'s
    `get_buf(PIPE_MTE3, 0, 0)`, serializing them.
    Measured 0 failures in 12 runs, **without needing `auto_mutex`**.
    """
    path = _write(
        tmp_path,
        INIT + f"    g = pl.make_tile_group(type={TILE}, addrs=0x0000, mutex_ids=[0])\n"
        "    with pl.section_vector():\n"
        "        pl.load(g.current(), x, [0, 0])\n",
    )
    assert _hits(path) == []


def test_bar_mte3_does_not_silence_it(tmp_path):
    """**Measured: still 6 failures in 12 runs**. `bar_*` is a barrier within one pipeline; draining MTE3 does not block
    writes from MTE2. Recognizing only `bar_all` is evidence-based, not over-conservative.
    """
    path = _write(
        tmp_path,
        INIT
        + "    pl.system.bar_mte3()\n"
        + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    assert _hits(path) == [(BODY, init_output.RULE, False)]


def test_a_kernel_without_init_output_is_out_of_scope(tmp_path):
    path = _write(
        tmp_path,
        f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
    )
    assert _hits(path) == []


def test_init_output_without_any_tile_passes(tmp_path):
    """A pure fill kernel: nothing else uses UB, so the 8 KB region has no competing access."""
    path = _write(tmp_path, INIT)
    assert _hits(path) == []


def test_a_plain_function_is_not_a_kernel(tmp_path):
    """Without `@pl.jit`, this is not a kernel; references and helper functions should not be affected by this rule."""
    text = (
        PREAMBLE
        + "def _reference(x, out):\n"
        + INIT
        + f"    src = pl.make_tile({TILE}, addr=0x0000)\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == []


# ---------------------------------------------------------------------------
# Counterexample declarations
# ---------------------------------------------------------------------------


def test_a_declared_counterexample_is_waived_but_still_printed(tmp_path):
    """A kernel with a distant address may be falsely reported (this rule does not check addresses), so waive it with a
    declaration.
    Put the computed byte distance in the reason—this is how `init_and_insert` arrived at `VA_SAFE = 0x2000`.
    """
    path = _write(
        tmp_path,
        INIT + f"    src = pl.make_tile({TILE}, addr=0x2000)\n"
        "    with pl.section_vector():\n"
        "        pl.load(src, x, [0, 0])\n",
        docstring=f"反例：{init_output.RULE} —— tile 在 0x2000，"
        "FP32 的覆写宽度是 8192 字节，不重叠",
    )
    hits = _hits(path)
    assert hits == [(BODY + 2, init_output.RULE, True)], hits


def test_a_stale_declaration_is_itself_reported(tmp_path):
    """When the declaration remains but the violation is gone, **report the stale declaration itself**—an outdated
    waiver could hide a real future issue.
    Report the `def` line (`BODY - 1`), not the decorator line.
    """
    path = _write(
        tmp_path,
        INIT
        + "    pl.system.bar_all()\n"
        + f"    src = pl.make_tile({TILE}, addr=0x0000)\n",
        docstring=f"反例：{init_output.RULE} —— 声明留着但屏障已经加上了",
    )
    assert _hits(path) == [(BODY - 1, init_output.RULE, False)]
